Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <iostream>
#include <cmath>
#include <cstdio>
#include <algorithm>
#include <string>
#include <vector>
#include <queue>
#include <string.h>
#include <map>
#include <fstream>
#include <functional>
#include <bitset>
#include <iomanip>
#include <stack>
#include <set>
#include <climits>
#define MAX_N 1000100
#define PI 3.141592653589
#define EPS 1e-20
#define BS 10
#define MOD 1000000007
#define ZERO 10001
#define YJSNPI 8101919
#define INF (1 << 28)
#define ADD(a, b) a = (a + (ll)b) % MOD
#define MUL(a, b) a = (a * (ll)b) % MOD
#define MAX(a, b) a = max(a, b)
#define MIN(a, b) a = min(a, b)

using namespace std;

typedef pair<int, int> pi;
typedef unsigned long long ll;
typedef vector<ll> vec;
typedef vector<vec> mat;

ll N; int K;
mat R[40];
mat D[100][40];

void mat_init(mat& A, int a, int b) {
	A.resize(a);
	for(int i = 0; i < a; i++) A[i].resize(b, 0);
}

mat mul(const mat& A, const mat& B) {
	mat C(A.size(), vec(B[0].size()));
	for(int i = 0; i < A.size(); i++) 
		for(int k = 0; k < B.size(); k++) 
			for(int j = 0; j < B[0].size(); j++) 
				ADD(C[i][j], A[i][k] * B[k][j]);
	return C;
}

void show_mat(const mat& A) {
	for(int i = 0; i < A.size(); i++) {
		for(int j = 0; j < A[0].size(); j++) {
			cout << A[i][j] << " ";
		}
		cout << endl;
	}
	cout << endl;
}

int main() {
	cin >> N >> K;
	int cnt = 0; ll nN = 1;
	while(nN <= N) { nN *= K; cnt++; }
	nN /= K;
	vector<int> d(cnt);
	for(int i = 0; i < cnt; i++) {
		d[i] = N / nN;
		N %= nN; nN /= K;
		//cout << d[i];
	}
	//cout << endl;
	for(int i = 0; i <= K; i++) mat_init(R[i], K + 1, K + 1);
	for(int i = 0; i <= cnt; i++) 
		for(int j = 0; j < K; j++) mat_init(D[i][j], K + 1, K + 1);
	R[0][K][K] = 1; R[1][K][K] = 1;
	for(int j = 0; j < K; j++) R[0][j][j] = 1;
	for(int j = 0; j < K; j++) R[1][(j + K - 1) % K][j] = 1;
	for(int j = 2; j <= K; j++) R[j] = mul(R[j - 1], R[1]);
	for(int j = 0; j <= K; j++) D[0][0][j][j] = 1;
	for(int j = 0; j <= K; j++) D[0][0][j][0] = 1;
	for(int i = 0; i <= cnt; i++) {
		for(int j = 1; j < K; j++) {
			D[i][j] = mul(D[i][j - 1], mul(mul(R[K - j], D[i][0]), R[j]));
		}
		D[i + 1][0] = D[i][K - 1];
		//for(int j = 0; j < K; j++) show_mat(D[i][j]);
	}
	mat ans(1, vec(K + 1, 0)); ans[0][K] = 1;
	int md = 0;
	for(int i = 0; i < cnt; i++) {
		if(d[i] != 0) ans = mul(ans, mul(mul(R[K - md], D[cnt - i - 1][d[i] - 1]), R[md]));
		//show_mat(ans);
		md += d[i]; md %= K;
	}
	ll res = 0;
	//show_mat(ans);
	for(int i = 0; i < K + 1; i++) ADD(res, ans[0][i]);
	cout << res << endl;
}

